#include <omp.h>
#include <vector>

double productWithInverses(std::vector<double> const& x) {
    double prod = 1.0;
    #pragma omp parallel for reduction(*:prod)
    for (size_t i = 0; i < x.size(); ++i) {
        double term = (i % 2 == 0) ? x[i] : 1.0 / x[i];
        prod *= term;
    }
    return prod;
}
